<?php require __DIR__.'/_guard.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){Security::verify();$id=(int)$_POST['product_id'];$delta=(int)$_POST['delta'];db()->beginTransaction();try{db()->prepare('UPDATE products SET stock=GREATEST(0,stock+?) WHERE id=?')->execute([$delta,$id]);db()->prepare('INSERT INTO stock_movements(product_id,quantity_change,reason,user_id) VALUES(?,?,?,?)')->execute([$id,$delta,substr($_POST['reason'],0,100),Auth::user()['id']]);db()->commit();$msg='Stock updated';}catch(Throwable $e){db()->rollBack();throw $e;}}$rows=db()->query('SELECT id,name,sku,stock,low_stock_threshold FROM products ORDER BY stock ASC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="/assets/css/admin.css"></head><body><main class="wide"><a href="/admin/">← Dashboard</a><h1>Inventory control</h1><p><?=e($msg)?></p><table><tr><th>Product</th><th>SKU</th><th>Stock</th><th>Adjust</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['sku'])?></td><td><?=$r['stock']?> <?=((int)$r['stock']<=(int)$r['low_stock_threshold']?'<b class="danger">LOW</b>':'')?></td><td><form method="post"><?=Security::field()?><input type="hidden" name="product_id" value="<?=$r['id']?>"><input type="number" name="delta" required placeholder="+/- qty"><input name="reason" required placeholder="Reason"><button>Adjust</button></form></td></tr><?php endforeach;?></table></main></body></html>